function colorGraph(nodes, edges){
  var adj={}; nodes.forEach(function(n){adj[n]=[];});
  edges.forEach(function(e){ adj[e[0]].push(e[1]); adj[e[1]].push(e[0]); });
  var order=nodes.slice().sort(function(a,b){return adj[b].length-adj[a].length;});
  var color={};
  order.forEach(function(n){ var neigh={}; adj[n].forEach(function(m){ if(color[m]!==undefined) neigh[color[m]]=1; });
    var c=0; while(neigh[c]) c++; color[n]=c; });
  var valid=true; edges.forEach(function(e){ if(color[e[0]]===color[e[1]]) valid=false; });
  var used={}; nodes.forEach(function(n){ used[color[n]]=1; });
  return {color:color, colorsUsed:Object.keys(used).length, valid:valid};
}
var EXPORTS={colorGraph:colorGraph};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ColoringForgePure = EXPORTS; }
